mkdir -p src test && cat > package.json <<'EOF'
{
  "name": "set-proto",
  "version": "0.1.0",
  "description": "Cross-platform helper to set the prototype of an object at runtime",
  "main": "src/index.js",
  "types": "src/index.d.ts",
  "files": ["src"],
  "scripts": {
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": ["prototype", "setPrototypeOf", "__proto__"],
  "license": "MIT"
}
EOF
cat > src/index.js <<'EOF'
'use strict';

/**
 * Set the prototype of `obj` to `proto` and return `obj`.
 *
 * Uses the standard Object.setPrototypeOf when available, falling back to
 * the legacy `__proto__` setter, and finally to copying properties for
 * engines that support neither.
 *
 * @template T
 * @param {T} obj
 * @param {object | null} proto
 * @returns {T}
 */
const setPrototypeOf =
  typeof Object.setPrototypeOf === 'function'
    ? Object.setPrototypeOf
    : { __proto__: [] } instanceof Array
      ? setProtoOf
      : mixinProperties;

function setProtoOf(obj, proto) {
  obj.__proto__ = proto;
  return obj;
}

function mixinProperties(obj, proto) {
  for (const prop in proto) {
    if (!Object.prototype.hasOwnProperty.call(obj, prop)) {
      obj[prop] = proto[prop];
    }
  }
  return obj;
}

module.exports = setPrototypeOf;
module.exports.setPrototypeOf = setPrototypeOf;
EOF
cat > src/index.d.ts <<'EOF'
declare function setPrototypeOf<T>(obj: T, proto: object | null): T;
declare namespace setPrototypeOf {
  export { setPrototypeOf };
}
export = setPrototypeOf;
EOF
cat > test/index.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const setPrototypeOf = require('..');

test('sets the prototype and returns the object', () => {
  const proto = { greet() { return 'hi'; } };
  const obj = {};
  assert.strictEqual(setPrototypeOf(obj, proto), obj);
  assert.strictEqual(Object.getPrototypeOf(obj), proto);
  assert.strictEqual(obj.greet(), 'hi');
});

test('accepts null', () => {
  const obj = setPrototypeOf({}, null);
  assert.strictEqual(Object.getPrototypeOf(obj), null);
});

test('named export matches default', () => {
  assert.strictEqual(setPrototypeOf.setPrototypeOf, setPrototypeOf);
});
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
transcript.jsonl
EOF
cat > README.md <<'EOF'
# set-proto

Cross-platform helper to set the prototype of an object at runtime.

```js
const setPrototypeOf = require('set-proto');

const obj = setPrototypeOf({}, { greet() { return 'hi'; } });
obj.greet(); // 'hi'
```

Uses `Object.setPrototypeOf` when available, falling back to `__proto__`,
then to copying properties on engines that support neither. No dependencies.

## Test

```sh
npm test
```
EOF
npm test 2>&1 | tail -12

